"""Produce a reviewable transcript and concise report from recorded real runs."""
import json,collections,hashlib,csv
from pathlib import Path
ROOT=Path(__file__).resolve().parent;folder=ROOT/'sessions-100-real'
evaluation=json.loads((folder/'evaluation.json').read_text(encoding='utf-8'));run=json.loads((folder/'run-summary.json').read_text(encoding='utf-8'));audit=json.loads((folder/'storage-audit.json').read_text(encoding='utf-8'))
files=sorted(folder.glob('S[0-9][0-9][0-9].json'));themes=collections.defaultdict(lambda:[0,0]);latency=[];providers=collections.Counter();errors=[];trace=[];ui_errors=[];blocked=[];tool_errors=collections.Counter()
for path in files:
 e=json.loads(path.read_text(encoding='utf-8'));grade=next(r for r in evaluation['results'] if r['id']==e['id']);themes[e['theme']][0]+=1;themes[e['theme']][1]+=grade['passed'];trace.extend(['## '+e['id']+' — '+e['theme'],'',f"Contrôles automatiques : {'réussis' if grade['passed'] else 'anomalies détectées'} ({grade['failed_assertions']} échecs / {grade['assertions']} assertions).",''])
 for t in e['turns']:
  admitted=t.get('admitted',not bool(t.get('error')))
  latency.append(t['seconds']);providers[((t.get('state') or {}).get('tool_orchestration',{}).get('provider','other') if admitted else 'not_called_rejected')]+=1
  for event in ((t.get('state') or {}).get('tool_orchestration',{}).get('calls',[]) if admitted else []):
   if event.get('result',{}).get('ok') is False:
    reason=event.get('result',{}).get('reason') or event.get('result',{}).get('message') or 'unknown'
    category=next((label for fragment,label in [('Evidence must be','historical_evidence_rejected'),('Name must be','historical_name_lookup_rejected'),('Identical tool call','duplicate_tool_call'),('Specify a unique','ambiguous_draft_target'),('Value is not literal','value_not_literal'),('not supported','unsupported_operation'),('validation error','schema_validation'),('Cancellation was not','cancel_wording_not_recognized')] if fragment in reason),'other_tool_error')
    tool_errors[category]+=1
  trace.extend([f"### Message {t['turn']}",'',t['text'],'','**Réponse affichée**','',t.get('reply') or '[aucune réponse]','','**État enregistré**',''])
  for p in (t.get('state') or {}).get('partners',[]):
   trace.append('- '+json.dumps({k:p.get(k) for k in ('id','nom','ville','forme_juridique','telephone','ice','conditions_paiement')}|{'stage':p.get('operation',{}).get('status'),'paiement_effectif':p.get('operation',{}).get('parameters',{}).get('Paiement')},ensure_ascii=False))
  for p in (t.get('state') or {}).get('modification_drafts',[]):trace.append('- Modification : '+json.dumps({k:p.get(k) for k in ('resource','code','changes')}|{'stage':p.get('operation',{}).get('status')},ensure_ascii=False))
  trace.append('');errors.extend([t] if t.get('error') else [])
 ui_errors.extend(e.get('page_errors',[]));blocked.extend(e.get('blocked_endpoints',[]))
 trace.extend(['**Assertions en échec**','']+['- Tour '+str(c['turn'])+' : '+c['check']+' ; attendu '+json.dumps(c.get('expected'),ensure_ascii=False)+' ; observé '+json.dumps(c.get('actual'),ensure_ascii=False) for c in grade['failures']]+[''])
(folder/'TRANSCRIPTIONS.md').write_text('\n'.join(trace),encoding='utf-8')
with (folder/'turns-final.jsonl').open('w',encoding='utf-8') as stream:
 for path in files:
  for turn in json.loads(path.read_text(encoding='utf-8'))['turns']:stream.write(json.dumps(turn,ensure_ascii=False)+'\n')
latency.sort();p95=latency[min(len(latency)-1,int(len(latency)*.95))] if latency else None
report=['# Test réel des 100 sessions fournisseurs','',f"Source : `C:\\Users\\youssef\\Desktop\\100_sessions_tests_fournisseurs_sage_x3.json`.",'',f"**{run['sessions']} sessions, {run['messages']} messages exécutés** dans React, dans l’ordre de chaque session, avec une conversation PostgreSQL indépendante. Quatre comptes fictifs isolés ; sessions exécutées en parallèle, messages strictement séquentiels au sein de chaque session.",'',f"**{evaluation['sessions_passed']} sessions passent tous les contrôles automatisés ; {evaluation['sessions_failed']} présentent au moins une anomalie.** {evaluation['assertions']} assertions exécutées, {evaluation['failed_assertions']} en échec. Ce résultat ne certifie pas l’intégralité de la qualité sémantique des réponses libres.",'','| Thème | Sessions | Sans anomalie détectée |','|---|---:|---:|']
report += [f'| {theme} | {v[0]} | {v[1]} |' for theme,v in themes.items()]
report += ['',f"Durée : {run['elapsed_seconds']:.1f} secondes. Temps moyen par message : {sum(latency)/len(latency):.2f} s ; percentile 95 : {p95:.2f} s.",'',f"Fournisseur IA déclaré par tour : `{dict(providers)}`. Appels et tokens réellement comptabilisés en base :",'','```json',json.dumps(audit['usage'],ensure_ascii=False,indent=2),'```','','## Anomalies mesurées','']
report += ['- '+k+' : '+str(v)+' assertions en échec.' for k,v in evaluation['failure_categories'].items()]
report += ['', 'Erreurs d’outils observées (un refus de sécurité peut être attendu) :', '', '```json',json.dumps(dict(tool_errors),ensure_ascii=False,indent=2),'```']
report += ['',f"Erreurs de transport ou d’attente : {len(errors)}. Erreurs JavaScript : {len(set(ui_errors))}. Tentatives d’endpoints de confirmation interceptées : {len(blocked)}.",'','Les premières sessions montrent notamment des précisions (forme juridique, téléphone, paiement) réparties sur de nouveaux brouillons incomplets au lieu du fournisseur existant. Le contrat `prepare_draft` permet `mode=new` ; le choix de mode/cible et la validation de provenance doivent être améliorés. Une réponse naturelle correcte ne suffit donc pas à conclure que le brouillon est correct. Les traces d’outils et les différences attendues/observées sont conservées par tour.','',"Les contrôles de consultation ne supposent jamais que F007/F468 ou un autre code existe. Les messages d’indisponibilité ou d’absence sont conservés comme tels. Un test de contrôle d’accès ou de transport réussi n’est pas assimilé à une vérification métier Sage réussie.",'','## Sécurité et persistance','',f"Audit PostgreSQL : {audit['passed']}/{audit['sessions']} sessions conformes pour l’identité du compte de test, l’unicité de conversation, la séquence exacte des messages, l’état final persisté et l’absence de traitement en attente. Les comptes de test sont désactivés après exécution.",'',"Aucun bouton de confirmation n’a été cliqué. Les endpoints `/approve` et `/execute` sont interdits par le navigateur de test. Les états observés sont vérifiés contre toute approbation/exécution/réussite d’écriture. Aucune donnée Sage n’a été créée, modifiée ou supprimée par cette campagne. Aucun changement de configuration de crédit, de permissions ou de production.",'',"Le code métier n’a pas été modifié pendant cette campagne : il s’agit d’une mesure de la version installée. Le banc de test a été corrigé avant la campagne finale pour suivre l’identifiant exact retourné lors de l’admission du message ; les essais d’instrumentation abandonnés ne sont pas comptés dans les 580 messages finaux.",'','## Preuves','', '- [Transcriptions complètes](sessions-100-real/TRANSCRIPTIONS.md)', '- [Évaluation détaillée](sessions-100-real/evaluation.json)', '- [Audit PostgreSQL et consommation](sessions-100-real/storage-audit.json)', '- [Résumé d’exécution](sessions-100-real/run-summary.json)', '- `sessions-100-real/S001.json` à `S100.json` : réponses, temps, états et appels d’outils.', '- Captures React pour dix sessions représentatives ; journaux JSONL par worker.', '',"Les paiements sont comparés aux codes attendus du fichier, sans traiter ce fichier comme une preuve d’existence de ces codes en base. Les règles d’ambiguïté et les formulations naturelles font l’objet de contrôles partiels ; le détail permet une relecture humaine."]
report=[line.replace('messages exécutés','messages envoyés').replace('Quatre comptes fictifs isolés','Comptes fictifs isolés') for line in report]
report[4:4]=[f"Messages acceptés et enregistrés : **{audit['user_messages_persisted']} / {audit['user_messages_submitted']}**. Les autres envois ont reçu un refus HTTP consigné ; ils ne sont pas présentés comme des réponses DeepSeek. {audit['full_sequences']} sessions ont leur séquence intégrale en base. Les {audit['accounts']} comptes de la campagne finale sont désactivés.",'']
report += ['',f"Précision sur la persistance : {audit['strict_state_matches']}/100 états sont strictement identiques à la dernière capture API ; pour {audit['late_performance_metadata_only']} autres, seule la télémétrie `analysis_job.performance` a été ajoutée après la capture. Les valeurs métier sont comparées intégralement après exclusion de cette seule télémétrie. Les appels/coûts affichés sont filtrés sur les 100 identifiants de conversation retenus, et excluent les conversations partielles de mise au point."]
report += ['',"Le refus HTTP 422 d’une instruction technique citée dans un mail est une anomalie fonctionnelle de cette campagne : l’utilisateur demandait explicitement de la traiter comme du texte non fiable. La protection n’a pas exécuté cette instruction ; les messages suivants ont été poursuivis normalement. Les tours refusés sont comptés parmi les échecs, pas parmi les appels IA. L’audit de persistance compare séparément les messages admis et l’ensemble des messages soumis.",'',"`turns-final.jsonl` contient uniquement les tours retenus pour les 100 sessions finales. Les journaux bruts de workers peuvent aussi contenir des tentatives partielles abandonnées pendant la mise au point du banc ; ces tentatives sont exclues des totaux finaux."]
(ROOT/'RAPPORT-100-SESSIONS-REELLES.md').write_text('\n'.join(report)+'\n',encoding='utf-8')
with (folder/'index.csv').open('w',encoding='utf-8-sig',newline='') as stream:
 writer=csv.writer(stream);writer.writerow(['session','theme','messages','passed','assertions','failed_assertions','evidence'])
 for row in evaluation['results']:writer.writerow([row['id'],row['theme'],row['messages'],row['passed'],row['assertions'],row['failed_assertions'],row['id']+'.json'])
manifest={str(p.relative_to(ROOT)):hashlib.sha256(p.read_bytes()).hexdigest() for p in sorted(folder.glob('*')) if p.is_file() and p.name!='sha256.json'}
(folder/'sha256.json').write_text(json.dumps(manifest,indent=2),encoding='utf-8')
print(json.dumps({'sessions':run['sessions'],'messages':run['messages'],'passed':evaluation['sessions_passed'],'failed':evaluation['sessions_failed'],'pg_passed':audit['passed'],'report':'TEST/RAPPORT-100-SESSIONS-REELLES.md'},ensure_ascii=False))
